package in.aicon.pocket;
import android.content.Context;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;
/** Original floating dock. Only the captured backdrop is blurred,
 * never the icons/text. A bounded reduced-resolution blur works across supported Android versions.
 * Snapshot work is bounded to the dock and coalesced while scrolling. */
final class GlassDock extends FrameLayout {
 final ScrollView source;final ImageView backdrop;final Handler handler=new Handler(Looper.getMainLooper());boolean queued;Bitmap prior;final PillSurface pill;final android.view.ViewTreeObserver.OnScrollChangedListener scrollListener=this::queue;
 GlassDock(Context c,ScrollView source,View navigation,int previous,int selected,int accent){super(c);this.source=source;GradientDrawable outline=new GradientDrawable();outline.setColor(0xff101820);outline.setCornerRadius(100*c.getResources().getDisplayMetrics().density);outline.setStroke(Math.max(1,Math.round(c.getResources().getDisplayMetrics().density)),0x663c4b58);setBackground(outline);setClipToOutline(true);setElevation(6*c.getResources().getDisplayMetrics().density);backdrop=new ImageView(c);backdrop.setScaleType(ImageView.ScaleType.FIT_XY);backdrop.setAlpha(.48f);addView(backdrop,new LayoutParams(-1,-1));pill=new PillSurface(c.getResources().getDisplayMetrics().density,previous,selected,Math.max(1,((ViewGroup)navigation).getChildCount()),accent);navigation.setBackground(new LayerDrawable(new Drawable[]{new DockSurface(),pill}));handler.post(()->pill.start());addView(navigation,new LayoutParams(-1,-2));source.getViewTreeObserver().addOnScrollChangedListener(scrollListener);addOnLayoutChangeListener((v,a,b,d,e,f,g,h,i)->queue());}
 void queue(){if(queued)return;queued=true;handler.postDelayed(()->{queued=false;capture();},120);}
 void capture(){if(!isAttachedToWindow()||getWidth()<=0||getHeight()<=0||source.getWidth()<=0)return;int[] from=new int[2],to=new int[2];source.getLocationInWindow(from);getLocationInWindow(to);Bitmap next=Bitmap.createBitmap(getWidth(),getHeight(),Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(next);canvas.drawColor(0xff071014);canvas.translate(from[0]-to[0],from[1]-to[1]);source.draw(canvas);Bitmap small=Bitmap.createScaledBitmap(next,Math.max(1,getWidth()/12),Math.max(1,getHeight()/12),true);next.recycle();int w=small.getWidth(),h=small.getHeight();int[] pixels=new int[w*h],out=new int[w*h];small.getPixels(pixels,0,w,0,0,w,h);for(int y=0;y<h;y++)for(int x=0;x<w;x++){long rr=0,gg=0,bb=0;int count=0;for(int dy=-2;dy<=2;dy++)for(int dx=-2;dx<=2;dx++){int px=pixels[Math.max(0,Math.min(h-1,y+dy))*w+Math.max(0,Math.min(w-1,x+dx))];rr+=(px>>16)&255;gg+=(px>>8)&255;bb+=px&255;count++;}out[y*w+x]=Color.rgb((int)(rr/count),(int)(gg/count),(int)(bb/count));}small.setPixels(out,0,w,0,0,w,h);if(prior!=null&&!prior.isRecycled()){backdrop.setImageDrawable(null);prior.recycle();}prior=small;backdrop.setImageBitmap(small);}
 @Override protected void onDetachedFromWindow(){handler.removeCallbacksAndMessages(null);pill.stop();if(source.getViewTreeObserver().isAlive())source.getViewTreeObserver().removeOnScrollChangedListener(scrollListener);queued=false;backdrop.setImageDrawable(null);if(prior!=null){prior.recycle();prior=null;}super.onDetachedFromWindow();}
 @Override protected void dispatchDraw(Canvas c){int saved=c.save();Path clip=new Path();float r=getHeight()/2f;clip.addRoundRect(new RectF(0,0,getWidth(),getHeight()),r,r,Path.Direction.CW);c.clipPath(clip);super.dispatchDraw(c);c.restoreToCount(saved);}
 static final class PillSurface extends Drawable{final Paint p=new Paint(3);final float d;final int from,to,slots,accent;float value;android.animation.ValueAnimator animator;void stop(){if(animator!=null)animator.cancel();}PillSurface(float d,int from,int to){this(d,from,to,4,0xff85d6b5);}PillSurface(float d,int from,int to,int slots,int accent){this.d=d;this.from=from;this.to=to;this.slots=Math.max(1,slots);this.accent=accent;value=from;}void start(){stop();if(from==to||!HisabDesign.animationsEnabled()){value=to;invalidateSelf();return;}android.animation.ValueAnimator a=android.animation.ValueAnimator.ofFloat(from,to);animator=a;a.setDuration(HisabDesign.MOTION_STANDARD_MS);a.setInterpolator(new android.view.animation.DecelerateInterpolator());a.addUpdateListener(v->{value=(Float)v.getAnimatedValue();invalidateSelf();});a.start();}@Override public void draw(Canvas c){Rect b=getBounds();float pad=7*d,w=(b.width()-pad*2)/slots;RectF r=new RectF(pad+value*w+2*d,6*d,pad+(value+1)*w-2*d,b.height()-6*d);p.setStyle(Paint.Style.FILL);p.setColor((accent&0x00ffffff)|0x35000000);c.drawRoundRect(r,r.height()/2,r.height()/2,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(d);p.setColor((accent&0x00ffffff)|0x78000000);c.drawRoundRect(r,r.height()/2,r.height()/2,p);}@Override public void setAlpha(int a){}@Override public void setColorFilter(ColorFilter f){}@Override public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
 static final class DockSurface extends Drawable{final Paint p=new Paint(3);@Override public void draw(Canvas c){RectF r=new RectF(getBounds());r.inset(1,1);p.setStyle(Paint.Style.FILL);p.setShader(new LinearGradient(0,0,0,r.height(),new int[]{0xaa253341,0xe6081018},null,Shader.TileMode.CLAMP));c.drawRoundRect(r,r.height()/2,r.height()/2,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.4f);p.setShader(new LinearGradient(0,0,r.width(),r.height(),new int[]{0x9ae4f6ff,0x224a7182,0x6687c4db},null,Shader.TileMode.CLAMP));c.drawRoundRect(r,r.height()/2,r.height()/2,p);p.setShader(null);}@Override public void setAlpha(int a){}@Override public void setColorFilter(ColorFilter f){}@Override public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
}
